import graphene
from graphene_file_upload.scalars import Upload
from graphql import GraphQLError
from .models import TenantPortalConfig

class UpdatePortalLogoMutation(graphene.Mutation):
    class Arguments:
        portal_slug = graphene.String(required=True)
        logo_image = Upload(required=True)

    logo_url = graphene.String()

    def mutate(self, info, portal_slug, logo_image):
        user = info.context.user
        if not user.is_authenticated:
            raise GraphQLError("Login required.")

        # Enforce that user is an administrator of the requested tenant portal
        config = TenantPortalConfig.objects.filter(
            slug=portal_slug,
            tenant__administrators=user
        ).first()
        if not config:
            raise GraphQLError("Portal configuration not found or access denied.")

        config.custom_logo = logo_image
        config.save(update_fields=["custom_logo"])
        return UpdatePortalLogoMutation(logo_url=config.custom_logo.url)
